import{R as t,e as a,f as s,U as i}from"./chunks/framework.ywem4qy5.js";const u=JSON.parse('{"title":"Calculations","description":"","frontmatter":{},"headers":[],"relativePath":"fields/calculations.md","filePath":"fields/calculations.md","lastUpdated":1778027571000}'),d={name:"fields/calculations.md"};function n(r,e,o,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="calculations" tabindex="-1">Calculations <a class="header-anchor" href="#calculations" aria-label="Permalink to &quot;Calculations&quot;">​</a></h1><p>Use Calculations when one field value should be derived from other fields instead of typed manually.</p><p>Calculations are useful for totals, scores, simple pricing, conditional formulas, and showing a result before final submission. They use expression syntax and field references, not Twig.</p><h2 id="key-settings" tabindex="-1">Key settings <a class="header-anchor" href="#key-settings" aria-label="Permalink to &quot;Key settings&quot;">​</a></h2><ul><li><strong>Formula</strong> - Define the expression used to calculate the field value.</li><li><strong>Variable picker</strong> - Insert references to other fields without typing handles manually.</li><li><strong>Prefix and suffix</strong> - Add display text such as currency symbols or units.</li><li><strong>Decimal handling</strong> - Control how numeric results are rounded or formatted.</li><li><strong>Visibility</strong> - Decide whether the calculated value should be shown to the user.</li></ul><h2 id="field-input-values" tabindex="-1">Field input values <a class="header-anchor" href="#field-input-values" aria-label="Permalink to &quot;Field input values&quot;">​</a></h2><p>Calculations work best with fields that produce numeric values. Number fields are read as numbers, and numeric-looking text values are cast to numbers before the formula is evaluated. That keeps expressions such as <code>1 + 2</code> numeric instead of joining the values as text.</p><p>For example, if <code>{field:a1b2c3}</code> is entered as <code>2</code> and <code>{field:d4e5f6}</code> is entered as <code>19.95</code>, this formula returns <code>39.9</code> before any number formatting is applied:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{field:a1b2c3} * {field:d4e5f6}</span></span></code></pre></div><p>Empty numeric values are treated as <code>0</code> for Number fields. Text or Email fields can be referenced, but they are safest for comparisons or string output rather than arithmetic unless their submitted values are always numeric.</p><h2 id="field-references" tabindex="-1">Field references <a class="header-anchor" href="#field-references" aria-label="Permalink to &quot;Field references&quot;">​</a></h2><p>Use the variable picker in the formula editor to insert fields from the current form. Formie inserts stable field-reference tokens such as:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{field:a1b2c3}</span></span></code></pre></div><p>Do not type a field handle directly in braces. Calculation formulas expect Formie field-reference tokens, and the actual reference value is generated by the picker.</p><p>Some fields expose more than one referenceable value. When a field has sub-values, the token can include a selector after the field reference:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{field:a1b2c3:firstName}</span></span></code></pre></div><p>The picker is the safest way to insert these references because it knows which fields and selectors are available for the formula.</p><h3 id="reference-transforms" tabindex="-1">Reference transforms <a class="header-anchor" href="#reference-transforms" aria-label="Permalink to &quot;Reference transforms&quot;">​</a></h3><p>Formie field references can include transforms in variable-aware contexts. Transforms are encoded on the reference token after the source value:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{field:a1b2c3;transform=round}</span></span></code></pre></div><p>Some transforms accept parameters:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{field:a1b2c3;transform=format;decimals=2;decimalPoint=.;thousandsSeparator=,}</span></span></code></pre></div><p>Available transforms include:</p><table tabindex="0"><thead><tr><th>Type</th><th>Transform</th><th>What it does</th></tr></thead><tbody><tr><td>Number</td><td><code>round</code></td><td>Rounds to the nearest whole number.</td></tr><tr><td>Number</td><td><code>floor</code></td><td>Rounds down to the nearest whole number.</td></tr><tr><td>Number</td><td><code>ceil</code></td><td>Rounds up to the nearest whole number.</td></tr><tr><td>Number</td><td><code>format</code></td><td>Formats numeric output with decimal precision and separators.</td></tr><tr><td>Text</td><td><code>lower</code></td><td>Converts text to lowercase.</td></tr><tr><td>Text</td><td><code>upper</code></td><td>Converts text to uppercase.</td></tr><tr><td>Text</td><td><code>title</code></td><td>Converts text to title case.</td></tr><tr><td>Text</td><td><code>capitalize</code></td><td>Capitalizes the first letter.</td></tr><tr><td>Text</td><td><code>replace</code></td><td>Replaces one text value with another.</td></tr><tr><td>Text</td><td><code>truncate</code></td><td>Truncates text to a maximum length.</td></tr><tr><td>Date</td><td><code>format</code></td><td>Formats date/time output with a preset or custom format pattern.</td></tr><tr><td>Boolean</td><td><code>map</code></td><td>Maps true/false values to custom labels.</td></tr></tbody></table><p>For calculation formulas, prefer the formula operators and the Calculations field’s number formatting settings for the final result. Use picker-generated references so the formula stays aligned with the field references Formie expects.</p><h2 id="formula-syntax" tabindex="-1">Formula syntax <a class="header-anchor" href="#formula-syntax" aria-label="Permalink to &quot;Formula syntax&quot;">​</a></h2><p>Calculations use an expression syntax based on <a href="https://symfony.com/doc/current/reference/formats/expression_language.html" target="_blank" rel="noreferrer">Symfony Expression Syntax</a>. <strong>They do not support Twig.</strong></p><p>Reference another field with the variable picker, which inserts a field-reference token:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{field:a1b2c3}</span></span></code></pre></div><p>Use arithmetic operators for numeric calculations:</p><table tabindex="0"><thead><tr><th>Operator</th><th>Meaning</th></tr></thead><tbody><tr><td><code>+</code></td><td>Addition</td></tr><tr><td><code>-</code></td><td>Subtraction</td></tr><tr><td><code>*</code></td><td>Multiplication</td></tr><tr><td><code>/</code></td><td>Division</td></tr><tr><td><code>%</code></td><td>Modulus</td></tr><tr><td><code>**</code></td><td>Power</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>({field:a1b2c3} * 50) + ({field:d4e5f6} * 25)</span></span></code></pre></div><p>Use comparison and logic operators for conditional expressions:</p><table tabindex="0"><thead><tr><th>Operator</th><th>Meaning</th></tr></thead><tbody><tr><td><code>==</code></td><td>Equal</td></tr><tr><td><code>!=</code></td><td>Not equal</td></tr><tr><td><code>&lt;</code> / <code>&gt;</code></td><td>Less than / greater than</td></tr><tr><td><code>&lt;=</code> / <code>&gt;=</code></td><td>Less than or equal / greater than or equal</td></tr><tr><td><code>and</code> / <code>&amp;&amp;</code></td><td>And</td></tr><tr><td><code>or</code> / \`</td><td></td></tr><tr><td><code>not</code> / <code>!</code></td><td>Not</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{field:a1b2c3} &gt; 10 and {field:d4e5f6} &lt; 100</span></span></code></pre></div><p>Other supported operators include strict comparisons such as <code>===</code> and <code>!==</code>, regex matching with <code>matches</code>, array checks with <code>in</code> and <code>not in</code>, ranges with <code>..</code>, and bitwise operators such as <code>&amp;</code>, <code>|</code> and <code>^</code>.</p><p>Use a ternary expression when the result depends on a condition:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{field:a1b2c3} &gt;= 10 ? {field:a1b2c3} * {field:d4e5f6} * 0.9 : {field:a1b2c3} * {field:d4e5f6}</span></span></code></pre></div><p>Use the string concatenation operator when the result should be text:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{field:a1b2c3:firstName} ~ &quot; &quot; ~ {field:a1b2c3:lastName}</span></span></code></pre></div><p>Keep formulas focused and test them in the field settings before publishing the form. If a formula depends on external data or complex branching, custom code or an integration is usually easier to maintain.</p><h2 id="submitted-value" tabindex="-1">Submitted value <a class="header-anchor" href="#submitted-value" aria-label="Permalink to &quot;Submitted value&quot;">​</a></h2><p>Calculations stores the calculated result. The submitted value is derived from other fields, so integrations and exports should treat it as computed output rather than user-entered input.</p><p>When querying or saving submissions through GraphQL, the field handle is used as the field name. Query the form’s <code>formFields</code> and include <code>inputTypeName</code> if you need to confirm the generated input type for a specific form.</p><h2 id="theme-config" tabindex="-1">Theme config <a class="header-anchor" href="#theme-config" aria-label="Permalink to &quot;Theme config&quot;">​</a></h2><p>The Calculations field can be targeted with the <code>calculations</code> theme config key.</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ craft.formie.renderForm(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;contactForm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    themeConfig: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        calculations: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            fieldInput: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                attributes: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                    class: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;my-calculation-output&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}) }}</span></span></code></pre></div><p>Use theme config for class and attribute changes. Use a template override only when the calculated output markup needs to change.</p><p>For full Tailwind, Bootstrap and other framework examples, see <a href="https://github.com/verbb/formie-theme-configs" target="_blank" rel="noreferrer">Formie theme configs</a>.</p><h2 id="front-end-reference" tabindex="-1">Front-end reference <a class="header-anchor" href="#front-end-reference" aria-label="Permalink to &quot;Front-end reference&quot;">​</a></h2><p>Calculations need Formie’s front-end JavaScript to update as dependent fields change. If you custom-render the form, keep the required front-end assets and field data available.</p><p>The front-end docs live on the separate browser UI reference site and cover rendered markup, data attributes, styling classes and JavaScript behavior for custom front-end implementations.</p><ul><li><a href="/browser/ui-reference/fields/calculations">Calculations</a></li></ul><h2 id="related-fields" tabindex="-1">Related fields <a class="header-anchor" href="#related-fields" aria-label="Permalink to &quot;Related fields&quot;">​</a></h2><ul><li>Use <a href="/fields/number">Number</a> for user-entered numeric values.</li><li>Use <a href="/fields/summary">Summary</a> to show a review of calculated and submitted values before final submission.</li></ul>`,55)])])}const f=t(d,[["render",n]]);export{u as __pageData,f as default};
